  private static func build(_ data: String) -> CGPath {
    let path = CGMutablePath()
    for contour in data.split(separator: "|") {
      var first = true
      for pt in contour.split(separator: " ") {
        let xy = pt.split(separator: ",")
        guard xy.count == 2, let x = Double(xy[0]), let y = Double(xy[1]) else { continue }
        let p = CGPoint(x: x, y: y)
        if first {
          path.move(to: p)
          first = false
        } else {
          path.addLine(to: p)
        }
      }
      path.closeSubpath()
    }
    return path
  }

  static let navyPath: CGPath = build(navyData)
  static let yellowPath: CGPath = build(yellowData)

  /// Draws the logo centred on (cx, cy) with the given [height] in points.
  static func draw(_ c: CGContext, cx: F, cy: F, height: F, alpha: F = 1) {
    if alpha <= 0 || height <= 0 { return }
    c.saveGState()
    c.translateBy(x: cx - height * aspect / 2, y: cy - height / 2)
    c.scaleBy(x: height, y: height)
    c.setFillColor(navy.withAlphaComponent(alpha).cgColor)
    c.addPath(navyPath)
    c.fillPath()
    c.setFillColor(yellow.withAlphaComponent(alpha).cgColor)
    c.addPath(yellowPath)
    c.fillPath()
    c.restoreGState()
  }
}
